<?php require 'includes/functions.php';require_login();$pdo=db();$items=cart_items();if(!$items){flash('warning','Your cart is empty.');go('cart.php');}$addresses=$pdo->prepare('SELECT * FROM addresses WHERE user_id=? ORDER BY is_default DESC,id DESC');$addresses->execute([user()['id']]);$addresses=$addresses->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='place'){$addressId=(int)($_POST['address_id']??0);$a=$pdo->prepare('SELECT * FROM addresses WHERE id=? AND user_id=?');$a->execute([$addressId,user()['id']]);$address=$a->fetch();$method=$_POST['payment_method']??'';$valid=in_array($method,['cod','upi','card','netbanking'],true);if(!$address||!$valid){flash('danger','Choose a shipping address and payment method.');go('checkout.php');}if($method==='upi'&&!preg_match('/^[\w.-]+@[\w.-]+$/',$_POST['upi_id']??'')){flash('danger','Enter a valid UPI ID.');go('checkout.php');}if($method==='card'&&(!preg_match('/^[0-9]{16}$/',str_replace(' ','',$_POST['card_number']??''))||!preg_match('/^[0-9]{3,4}$/',$_POST['cvv']??''))){flash('danger','Enter valid simulated card details.');go('checkout.php');}$totals=cart_totals();try{$pdo->beginTransaction();foreach($items as $i){$s=$pdo->prepare('SELECT stock_quantity FROM product_sizes WHERE product_id=? AND size=? FOR UPDATE');$s->execute([$i['id'],$i['size']]);if((int)$s->fetchColumn()<$i['qty'])throw new Exception($i['name'].' is no longer available in this quantity.');}$orderNo='OVR-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6));$addressText=$address['full_name'].', '.$address['address'].', '.$address['city'].', '.$address['state'].' - '.$address['pincode'];$coupon=$_SESSION['coupon']['id']??null;$o=$pdo->prepare('INSERT INTO orders(order_number,user_id,coupon_id,shipping_address,billing_address,subtotal,coupon_discount,tax,delivery_charge,total_amount,payment_method,payment_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$status=$method==='cod'?'pending':'paid';$o->execute([$orderNo,user()['id'],$coupon,$addressText,$addressText,$totals['subtotal'],$totals['couponDiscount'],$totals['tax'],$totals['delivery'],$totals['grand'],$method,$status]);$orderId=(int)$pdo->lastInsertId();foreach($items as $i){$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,size,quantity,unit_price) VALUES(?,?,?,?,?,?)')->execute([$orderId,$i['id'],$i['name'],$i['size'],$i['qty'],$i['unit_price']]);$pdo->prepare('UPDATE product_sizes SET stock_quantity=stock_quantity-? WHERE product_id=? AND size=?')->execute([$i['qty'],$i['id'],$i['size']]);$pdo->prepare('UPDATE products SET stock_quantity=GREATEST(0,stock_quantity-?),sales_count=sales_count+? WHERE id=?')->execute([$i['qty'],$i['qty'],$i['id']]);}$pdo->prepare('INSERT INTO payments(order_id,method,amount,status,transaction_ref) VALUES(?,?,?,?,?)')->execute([$orderId,$method,$totals['grand'],$status,'SIM-'.strtoupper(bin2hex(random_bytes(3)))]);if($coupon){$pdo->prepare('UPDATE coupons SET used_count=used_count+1 WHERE id=?')->execute([$coupon]);$pdo->prepare('INSERT INTO coupon_usage(coupon_id,user_id,order_id) VALUES(?,?,?)')->execute([$coupon,user()['id'],$orderId]);}$pdo->commit();unset($_SESSION['cart'],$_SESSION['coupon']);go('order-success.php?id='.$orderId);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger',$e->getMessage());go('checkout.php');}}$totals=cart_totals();$pageTitle='Checkout';require 'includes/header.php';require 'includes/navbar.php'; ?>
<main class="container my-5"><h1 class="section-title">Checkout</h1><p class="text-muted">1. Cart review → 2. Shipping address → 3. Billing address → 4. Payment</p><div class="row g-4"><div class="col-lg-7"><form method="post" class="card card-body"><input type="hidden" name="action" value="place"><h5>Shipping & billing address</h5><?php foreach($addresses as $a): ?><label class="border p-3 mb-2"><input type="radio" name="address_id" value="<?=$a['id']?>" <?=$a['is_default']?'checked':''?>> <b><?=e($a['full_name'])?></b> · <?=e($a['mobile'])?><br><span class="ms-4"><?=e($a['address'])?>, <?=e($a['city'])?>, <?=e($a['state'])?> - <?=e($a['pincode'])?></span></label><?php endforeach ?><?php if(!$addresses): ?><div class="alert alert-warning">Add an address before checkout.</div><?php endif ?><a href="<?=base('addresses.php')?>" class="mb-3">+ Add or edit address</a><h5>Simulated payment</h5><select class="form-select mb-2" name="payment_method" id="payment"><option value="cod">Cash on Delivery</option><option value="upi">UPI</option><option value="card">Card</option><option value="netbanking">Net Banking</option></select><div id="upiFields"><input class="form-control mb-2" name="upi_id" placeholder="UPI ID (for UPI payment)"></div><div id="cardFields"><input class="form-control mb-2" name="card_holder" placeholder="Cardholder name"><input class="form-control mb-2" name="card_number" placeholder="16-digit card number"><div class="row"><div class="col"><input class="form-control" name="expiry" placeholder="MM/YY"></div><div class="col"><input class="form-control" name="cvv" placeholder="CVV"></div></div></div><button class="btn btn-dark mt-4" <?=$addresses?'':'disabled'?>>Place order · <?=money($totals['grand'])?></button></form></div><div class="col-lg-5"><div class="card card-body"><h5>Order summary</h5><?php foreach($items as $i): ?><div class="d-flex justify-content-between mb-2"><span><?=e($i['name'])?> × <?=$i['qty']?> <small>(<?=$i['size']?>)</small></span><b><?=money($i['unit_price']*$i['qty'])?></b></div><?php endforeach ?><hr><div class="d-flex justify-content-between fw-bold"><span>Total</span><span><?=money($totals['grand'])?></span></div></div></div></div></main><script>document.getElementById('payment').onchange=function(){document.getElementById('upiFields').style.display=this.value==='upi'?'block':'none';document.getElementById('cardFields').style.display=this.value==='card'?'block':'none'};document.getElementById('payment').onchange();</script><?php require 'includes/footer.php'; ?>
